@sig trait PowerChargeCommandPolicy_Api {
  def id: Art.BridgeId
  def decisionSnapshot_Id : Art.PortId
  def powerCommand_Id : Art.PortId
  def chargeCommand_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var powerCommand: Drone_Lifecycle_Governor.PowerCommand.Type = $

  def put_powerCommand(value : Drone_Lifecycle_Governor.PowerCommand.Type) : Unit = {
    Contract(
      Modifies(powerCommand),
      Ensures(
        powerCommand == value
      )
    )
    Spec {
      powerCommand = value
    }

    Art.putValue(powerCommand_Id, Drone_Lifecycle_Governor.PowerCommand_Payload(value))
  }

  // Logika spec var representing port state for outgoing data port
  @spec var chargeCommand: Drone_Lifecycle_Governor.ChargeCommand.Type = $

  def put_chargeCommand(value : Drone_Lifecycle_Governor.ChargeCommand.Type) : Unit = {
    Contract(
      Modifies(chargeCommand),
      Ensures(
        chargeCommand == value
      )
    )
    Spec {
      chargeCommand = value
    }

    Art.putValue(chargeCommand_Id, Drone_Lifecycle_Governor.ChargeCommand_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class PowerChargeCommandPolicy_Initialization_Api (
  val id: Art.BridgeId,
  val decisionSnapshot_Id : Art.PortId,
  val powerCommand_Id : Art.PortId,
  val chargeCommand_Id : Art.PortId) extends PowerChargeCommandPolicy_Api

@datatype class PowerChargeCommandPolicy_Operational_Api (
  val id: Art.BridgeId,
  val decisionSnapshot_Id : Art.PortId,
  val powerCommand_Id : Art.PortId,
  val chargeCommand_Id : Art.PortId) extends PowerChargeCommandPolicy_Api {

  // Logika spec var representing port state for incoming data port
  @spec var decisionSnapshot: Drone_Lifecycle_Governor.DecisionSnapshot = $

  def get_decisionSnapshot() : Option[Drone_Lifecycle_Governor.DecisionSnapshot] = {
    Contract(
      Ensures(
        Res == Some(decisionSnapshot)
      )
    )
    val value : Option[Drone_Lifecycle_Governor.DecisionSnapshot] = Art.getValue(decisionSnapshot_Id) match {
      case Some(Drone_Lifecycle_Governor.DecisionSnapshot_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port decisionSnapshot.  Expecting 'Drone_Lifecycle_Governor.DecisionSnapshot_Payload' but received ${v}")
        None[Drone_Lifecycle_Governor.DecisionSnapshot]()
      case _ => None[Drone_Lifecycle_Governor.DecisionSnapshot]()
    }
    return value
  }
}
